editorAdapter.detectScript:
function() {
  // Keep the match narrow so the template does not accidentally claim unrelated pages.
  if (window.location.hostname !== 'example.com') {
    return null;
  }

  const root = document.querySelector('#your-editor-root[contenteditable="true"]');
  if (!root) {
    return null;
  }

  return {
    type: 'ExampleContentEditable',
    certainty: 1,
    source: 'selector: #your-editor-root[contenteditable="true"]'
  };
}

editorAdapter.injectScript:
function(url) {
  const root = document.querySelector('#your-editor-root[contenteditable="true"]');
  if (!root) {
    return false;
  }

  root.focus();

  const imgHtml = '<img src="' + url + '" alt="image" />';

  // First try the simple browser insertion path. Many legacy editors still support it.
  if (typeof document.execCommand === 'function') {
    const success = document.execCommand('insertHTML', false, imgHtml);
    if (success) {
      root.dispatchEvent(new Event('input', { bubbles: true }));
      root.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    }
  }

  // Fallback: insert into the current selection manually.
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) {
    root.insertAdjacentHTML('beforeend', imgHtml);
    root.dispatchEvent(new Event('input', { bubbles: true }));
    root.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  }

  const range = selection.getRangeAt(0);
  range.deleteContents();
  const wrapper = document.createElement('div');
  wrapper.innerHTML = imgHtml;
  const imageNode = wrapper.firstChild;
  if (!imageNode) {
    return false;
  }

  range.insertNode(imageNode);
  range.setStartAfter(imageNode);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);

  root.dispatchEvent(new Event('input', { bubbles: true }));
  root.dispatchEvent(new Event('change', { bubbles: true }));
  return true;
}
